const item = $input.first();
const body = item.json.body || item.json || {};
const binary = item.binary || {};
const firstBinaryKey = Object.keys(binary)[0];

if (!firstBinaryKey) {
  throw new Error('Missing resume DOCX file. Send multipart/form-data with file field name: resume');
}

const resumeBinary = binary[firstBinaryKey];
resumeBinary.fileExtension = 'zip';
resumeBinary.mimeType = 'application/zip';

return [{
  json: {
    applicant_name: body.name || body.applicant_name || body.applicantName || '',
    applicant_email: body.email || body.applicant_email || body.applicantEmail || '',
    job_description: body.job_description || body.jobDescription || body.jd || '',
    original_resume_file_name: binary[firstBinaryKey].fileName || 'resume.docx',
    submitted_at: new Date().toISOString()
  },
  binary: {
    resume: resumeBinary
  }
}];

const normalize = $('Normalize Input And DOCX Binary').first().json;
const item = $input.first();
const binary = item.binary || {};
const keys = Object.keys(binary);

function decodeXmlEntities(text) {
  return text
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&apos;/g, "'");
}

function xmlToText(xml) {
  return decodeXmlEntities(
    xml
      .replace(/<w:tab\/>/g, '\t')
      .replace(/<w:br\/>/g, '\n')
      .replace(/<w:p[^>]*>/g, '')
      .replace(/<\/w:p>/g, '\n')
      .replace(/<[^>]+>/g, '')
      .replace(/\n{3,}/g, '\n\n')
      .replace(/[ \t]{2,}/g, ' ')
      .trim()
  );
}

let resumeText = '';
const parsedFiles = [];

for (const key of keys) {
  const meta = binary[key];
  const fileName = meta.fileName || '';
  const directory = meta.directory || '';
  const fullPath = directory ? `${directory}/${fileName}` : fileName;

  const isDocument =
    fullPath === 'word/document.xml' ||
    /^word\/header\d+\.xml$/.test(fullPath) ||
    /^word\/footer\d+\.xml$/.test(fullPath);

  if (isDocument) {
    const buffer = await this.helpers.getBinaryDataBuffer(0, key);
    const xml = buffer.toString('utf8');
    const text = xmlToText(xml);

    if (text) {
      resumeText += text + '\n\n';
      parsedFiles.push(fullPath);
    }
  }
}

resumeText = resumeText.trim();

if (!resumeText) {
  throw new Error(
    `Could not extract text from DOCX. Found files: ${keys
      .map((key) => {
        const meta = binary[key];
        return meta.directory ? `${meta.directory}/${meta.fileName}` : meta.fileName;
      })
      .join(', ')}`
  );
}

return [
  {
    json: {
      applicant: {
        name: normalize.applicant_name,
        email: normalize.applicant_email
      },
      job_description: normalize.job_description,
      resume_text: resumeText,
      resume_source: {
        original_file_name: normalize.original_resume_file_name,
        parsed_docx_files: parsedFiles
      },
      submitted_at: normalize.submitted_at
    }
  }
];

const previous = $('Extract Text From DOCX XML').first().json;
const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { raw_response: raw, parse_error: e.message }; }
return [{ json: { ...previous, agents: { job_finder_agent: parsed } } }];

const previous = $('Parse Job Analysis').first().json;
const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { raw_response: raw, parse_error: e.message }; }
return [{ json: { ...previous, agents: { ...previous.agents, resume_matching_agent: parsed }, resume_match_analysis: parsed } }];

const previous = $('Parse Resume Match').first().json;
const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { raw_response: raw, parse_error: e.message }; }
return [{ json: { ...previous, agents: { ...previous.agents, resume_tailor_agent: parsed }, tailored_resume: parsed } }];

const previous = $('Parse Tailored Resume').first().json;
const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { raw_response: raw, parse_error: e.message }; }
return [{ json: { ...previous, agents: { ...previous.agents, cover_letter_agent: parsed }, cover_letter: parsed } }];

const previous = $('Parse Cover Letter').first().json;
const raw = $input.first().json.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(raw); } catch (e) { parsed = { raw_response: raw, parse_error: e.message }; }
return [{ json: { ...previous, agents: { ...previous.agents, critic_agent: parsed }, critic_review: parsed } }];

const data = $input.first().json;

const safeName = (data.applicant.name || 'Applicant')
  .replace(/[^a-z0-9 _-]/gi, '')
  .trim();

const role =
  data.agents.job_finder_agent.extracted_role ||
  data.agents.job_finder_agent.role ||
  'Target Role';

const company =
  data.agents.job_finder_agent.company ||
  'Target Company';

function cleanMarkdownForGoogleDocs(markdown) {
  if (!markdown) return '';

  return markdown
    // Remove mailto markdown links but keep email text
    .replace(/\[([^\]]+)\]\(mailto:[^)]+\)/gi, '$1')

    // Remove normal markdown links but keep visible text
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')

    // Convert H1 headings
    .replace(/^#\s+(.+)$/gm, '$1\n' + '='.repeat(42))

    // Convert H2 headings
    .replace(/^##\s+(.+)$/gm, '\n$1\n' + '-'.repeat(32))

    // Convert H3 headings
    .replace(/^###\s+(.+)$/gm, '\n$1')

    // Convert bullets
    .replace(/^\*\s+/gm, '- ')

    // Remove bold/italic markdown
    .replace(/\*\*([^*]+)\*\*/g, '$1')
    .replace(/\*([^*]+)\*/g, '$1')

    // Normalize spacing
    .replace(/[ \t]+$/gm, '')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const resumeMarkdown =
  data.tailored_resume.final_resume_markdown ||
  JSON.stringify(data.tailored_resume, null, 2);

const coverLetterMarkdown =
  data.cover_letter.final_cover_letter_markdown ||
  JSON.stringify(data.cover_letter, null, 2);

return [
  {
    json: {
      ...data,
      document_payloads: {
        tailored_resume_title: `Tailored Resume - ${safeName} - ${role}`,
        cover_letter_title: `Cover Letter - ${safeName} - ${company}`,
        tailored_resume_text: cleanMarkdownForGoogleDocs(resumeMarkdown),
        cover_letter_text: cleanMarkdownForGoogleDocs(coverLetterMarkdown)
      }
    }
  }
];

const data = $('Prepare Final Google Docs Content').first().json;
const resumeDoc = $('Create Final Tailored Resume Google Doc').first().json;
const coverDoc = $('Create Final Cover Letter Google Doc').first().json;

return [{
  json: {
    success: true,
    assistant: 'ApplyWise-style Groq AI job application assistant',
    applicant: data.applicant,
    submitted_at: data.submitted_at,
    input_summary: {
      original_resume_file_name: data.resume_source.original_file_name,
      parsed_docx_files: data.resume_source.parsed_docx_files,
      job_description_received: Boolean(data.job_description)
    },
    final_results: {
      tailored_resume: data.tailored_resume,
      cover_letter: data.cover_letter,
      resume_match_analysis: data.resume_match_analysis,
      critic_review: data.critic_review
    },
    agent_outputs: data.agents,
    google_docs: {
      tailored_resume: {
        id: resumeDoc.id,
        name: resumeDoc.name,
        url: 'https://docs.google.com/document/d/' + resumeDoc.id + '/edit'
      },
      cover_letter: {
        id: coverDoc.id,
        name: coverDoc.name,
        url: 'https://docs.google.com/document/d/' + coverDoc.id + '/edit'
      }
    }
  }
}];
